\begin{itemchoice}
			\itemch Ta có $A=(-7;5]$ và $B=(-1;+\infty)$. Mệnh đề $B=[-1;+\infty)$ là sai.
			\itemch $A\cap B = (-7;5] \cap (-1;+\infty) = (-1;5]$. Mệnh đề đúng.
			\itemch $A\cup B = (-7;5] \cup (-1;+\infty) = (-7;+\infty)$. Mệnh đề sai vì dùng ngoặc vuông $[-7$.
			\itemch $C_{\mathbb{R}}(A\cup B) = \mathbb{R} \setminus (-7;+\infty) = (-\infty;-7]$. Mệnh đề đúng.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Số tiền thu được từ hàng loại I là $160x$ (nghìn đồng), từ hàng loại II là $80y$ (nghìn đồng). Tổng số tiền là $160x+80y$ (nghìn đồng). Mệnh đề đúng.
			\itemch $40$ triệu đồng = $40.000$ nghìn đồng. Để cửa hàng có lãi (thu nhiều hơn chi phí, tức là số tiền thu được $>40$ triệu): $160x+80y > 40000 \Leftrightarrow 2x+y > 500$. (Mệnh đề dùng dấu $\ge$ là chỉ điểm hòa vốn, "có lãi" nên dùng dấu $>$, tuy nhiên trong thực tế kinh tế đôi khi người ta gộp chung. Hãy xem đáp án trường, đáp án trường cho là SAI, vậy chữ "có lãi" là dấu $>$, mệnh đề $\ge$ sai).
			\itemch Nếu $x=100, y=301 \Rightarrow 2x+y = 2(100)+301 = 501 > 500$. Thỏa mãn có lãi. Mệnh đề đúng.
			\itemch Nếu $x=230$, để có lãi: $2(230) + y > 500 \Leftrightarrow 460 + y > 500 \Leftrightarrow y > 40$. Vì $y \in \mathbb{N}$ nên $y \ge 41$. Vậy cần bán thêm ít nhất 41 sản phẩm loại II. Mệnh đề "ít nhất 40" là điểm hòa vốn, không phải có lãi. Mệnh đề sai.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Góc $90^\circ<\alpha<180^\circ$ (góc tù), $\sin \alpha>0$ và $\cos \alpha<0$ nên chúng trái dấu. Mệnh đề sai.
			\itemch Áp dụng công thức góc bù: $\cos(180^\circ-\alpha)=-\cos \alpha$, $\sin(180^\circ-\alpha)=\sin \alpha$. Vế trái bằng $-\cos \alpha + 2\sin \alpha = 2\sin \alpha - \cos \alpha$. Mệnh đề đúng.
			\itemch Có $\cos \alpha = -\sqrt{1-\sin^2 \alpha} = -\sqrt{1-\left(\displaystyle \frac{1}{3}\right)^2} = -\sqrt{\frac{8}{9}} = \frac{-2\sqrt{2}}{3}$. Đồng nhất với $\displaystyle \frac{-2\sqrt{b}}{c} \Rightarrow b=2, c=3$ (thỏa mãn phân số tối giản). Khi đó $b^2+c = 2^2+3 = 7 \ne 6$. Mệnh đề sai.
			\itemch Ta có $A = \displaystyle \frac{\cos^{2}\alpha - (1-\cos^{2}\alpha)}{\sin \alpha+\cos \alpha} = \frac{\cos^{2}\alpha-\sin^{2}\alpha}{\sin \alpha+\cos \alpha} = \frac{(\cos \alpha-\sin \alpha)(\cos \alpha+\sin \alpha)}{\sin \alpha+\cos \alpha} = \cos \alpha-\sin \alpha$. Mệnh đề cho $A=\sin \alpha+\cos \alpha$ là sai.
		\end{itemchoice}
